12	/** The figure a claim shows and totals: the due fixed when it was settled, else the greater of the
13	 *  sheet's floor in force on the claim's date and its figure, plus the late charge on that, where its figure is
14	 *  the one its person's last statement bound it to, else live at its person's grade's rate in force on
15	 *  the claim's date (null, n/a, when there is no rate). A correction has neither floor nor charge. Every rounding of a claim's live figures follows
16	 *  the sheet's rounding mode in force on the claim's date, else the sheet's policy date: half up for a claim dated before it, half to even on or after it. */
17	@Service
18	public class Figures {
19	
20	    private final Rates rates;
21	    private final Settings settings;
22	    private final Sheets sheets;
23	    private final Claims claims;
24	
25	    public Figures(Rates rates, Settings settings, Sheets sheets, Claims claims) {
26	        this.rates = rates;
27	        this.settings = settings;
28	        this.sheets = sheets;
29	        this.claims = claims;
30	    }
31	
32	    /** The sheet's policy date: as set, else the sheet's today. */
33	    public LocalDate policyDate(String sheetId) {
34	        LocalDate set = settings.policyDate(sheetId);
35	        return set != null ? set : sheets.today(sheetId);
36	    }
37	
38	    /** How the claim's live figures round: by the sheet's rounding mode in force on the claim's
39	     *  (rounding) date when one is; else half up when the claim is dated before the sheet's policy
40	     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
41	    public RoundingMode rounding(Claim claim) {
42	        RoundingMode set = settings.rounding(claim.getSheetId(), roundingDate(claim));
43	        if (set != null) return set;
44	        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
45	    }
46	
47	    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
48	    public LocalDate roundingDate(Claim claim) {
49	        if (claim.getCorrects() == null) return claim.getDate();
50	        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
51	        return corrected != null ? corrected : claim.getDate();
52	    }
53	
54	    /** The claim's due as the screen shows and totals it: its figure raised to the sheet's floor in
55	     *  force on the claim's date when it is below it, plus the late charge on that floored figure while
56	     *  it is overdue (a correction has neither). A settled claim's fixed due already holds the charge and floor it had then;
57	     *  a claim bound by a statement shows the due bound then, its late charge no longer following today. */
58	    public BigDecimal due(Claim claim, String grade) {
59	        BigDecimal figure = figure(claim, grade);
60	        if (figure == null || claim.getDue() != null || claim.isStated() || claim.isCorrection()) return figure;
61	        BigDecimal floored = figure.max(settings.floor(claim.getSheetId(), claim.getDate()));
62	        return floored.add(charge(claim, grade, floored));
63	    }
64	
65	    /** The claim's figure: the fixed due, else the bound due (with the late charge and floor it had when
66	     *  bound), else live without any late charge or floor.
67	     *  A PENDING claim is bound by a statement like any other: it shows its bound figure. */
68	    public BigDecimal figure(Claim claim, String grade) {
69	        if (claim.getDue() != null) return claim.getDue();
70	        if (claim.isStated()) return claim.getStatedDue();
71	        return live(claim, grade);
72	    }
73	
74	    /** The date the claim goes overdue after: its due-by (fixed when it was added) plus the grace days
75	     *  of its person's grade in force on the claim's date (`grade`), in force on that date. */
76	    public LocalDate overdueFrom(Claim claim, String grade) {
77	        return claim.getDueBy().plusDays(settings.grace(claim.getSheetId(), grade, claim.getDate()));
78	    }
79	
80	    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, and its due-by plus its grace
81	     *  (see {@link #overdueFrom}) is before the sheet's today. */
82	    public boolean overdue(Claim claim, String grade) {
83	        if (!claim.getStatus().isOpen() || claim.isDeferred()) return false;
84	        LocalDate today = sheets.today(claim.getSheetId());
85	        return today != null && overdueFrom(claim, grade).isBefore(today);
86	    }
87	
88	    /** The late charge on a figure of the claim: nothing unless the claim is OPEN (or PENDING), not deferred, and its due-by (fixed
89	     *  when it was added) plus its grace is before the sheet's today (a correction, or a claim whose charge is waived, has none); then, for every full 30 days it is
90	     *  overdue, counted from its due-by plus its grace, the sheet's late percent in force on that boundary date (the due-by plus
91	     *  the grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each rounded by the claim's rounding to two decimals, added up. A
92	     *  boundary whose percent is 0.00 adds nothing. It follows the sheet's today; a statement binds it into the claim's due (see {@link #due}). */
93	    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
94	        BigDecimal none = BigDecimal.ZERO.setScale(2);
95	        if (figure == null || !claim.getStatus().isOpen() || claim.isDeferred() || claim.isCorrection() || claim.isWaived()) return none;
96	        String sheetId = claim.getSheetId();
97	        LocalDate from = overdueFrom(claim, grade);
98	        long periods = ChronoUnit.DAYS.between(from, sheets.today(sheetId)) / 30;
99	        BigDecimal total = none;
100	        for (long k = 1; k <= periods; k++) {
101	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * k));
102	            if (pct.signum() == 0) continue;
103	            total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim)));
104	        }
105	        return total;
106	    }
107	
108	    /** The claim's due at its person's grade's rate in force on the claim's date (passing over a
109	     *  forward-only rate saved after the claim was added, see {@link Rates#ownPct}): amount times the
110	     *  rate divided by 100, rounded by the claim's rounding to two decimals, before any late charge or
111	     *  floor (see {@link #due}); null when there is no rate. */
112	    public BigDecimal live(Claim claim, String grade) {
113	        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate(), claim.seq());
114	        if (pct == null) return null;
115	        return claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
116	    }
117	}
