389	    public List<Claim> ofPerson(String sheetId, long personId) {
390	        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
391	                Claims::claim, sheetId, personId);
392	    }
393	
394	    /** Unbind every claim of the person a statement binds: each shows its live figure again. */
395	    public void unbind(String sheetId, long personId) {
396	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ? AND stated",
397	                sheetId, personId);
398	    }
399	
400	    /** Whether the person has a SETTLED claim with this number: one a correction may correct. */
401	    public boolean settled(String sheetId, long personId, String number) {
402	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
403	                Integer.class, sheetId, personId, number);
404	        return n != null && n > 0;
405	    }
406	
407	    /** What remains of the person's SETTLED claim with this number: its amount less the corrections
408	     *  already made against it (VOID or DELETED ones, and the claim `ownId` (null: none), left out). */
409	    public BigDecimal remaining(String sheetId, long personId, String number, Long ownId) {
410	        BigDecimal amount = jdbc.query("SELECT amount FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
411	                (rs, i) -> rs.getBigDecimal("amount"), sheetId, personId, number).stream().findFirst().orElse(BigDecimal.ZERO);
412	        BigDecimal corrections = jdbc.queryForObject("SELECT COALESCE(SUM(amount), 0) FROM claim WHERE sheet_id = ? AND person_id = ? AND corrects = ? "
413	                + "AND status NOT IN ('VOID', 'DELETED') AND id <> ?", BigDecimal.class, sheetId, personId, number, ownId != null ? ownId : -1L);
414	        return amount.add(corrections);
415	    }
416	
417	    /** Whether a claim on the sheet other than `ownId` (null: any) has this reference, without regard to case. */
418	    public boolean refUsed(String sheetId, String ref, Long ownId) {
419	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
420	                Integer.class, sheetId, ref, ownId != null ? ownId : -1L);
421	        return n != null && n > 0;
422	    }
423	
424	    /** The date of the person's claim with this number, or null when there is none. */
425	    public LocalDate dateOf(String sheetId, long personId, String number) {
426	        return jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?",
427	                (rs, i) -> rs.getDate("claim_date").toLocalDate(), sheetId, personId, number)
428	                .stream().findFirst().orElse(null);
429	    }
430	
431	    /** Move the claim to its (new) person: unbound from any statement, and listed as that person's newest claim. */
432	    public void reassign(Claim claim) {
433	        jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = FALSE, stated_due = NULL, listed = NEXT VALUE FOR claim_listed WHERE id = ?",
434	                claim.getPersonId(), claim.getNumber(), claim.getId());
435	    }
436	
437	    /** Release every editor's lock on the sheet's claims: the sheet's today has changed. */
438	    public void unlockAll(String sheetId) {
439	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
440	    }
441	
442	    /** Release the user's locks on the person's other claims: the person's one claim form edits one claim at a time. */
443	    public void unlockOthers(String sheetId, long personId, String user, long keptId) {
444	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
445	                sheetId, personId, user, keptId);
446	    }
447	
448	    /** Fix the claim's due-by again, at the date it now has. */
449	    public void redue(Claim claim) {
450	        jdbc.update("UPDATE claim SET due_by = ? WHERE id = ?", Date.valueOf(claim.getDueBy()), claim.getId());
451	    }
452	
453	    /** Record whether the claim is held. */
454	    public void hold(Claim claim) {
455	        jdbc.update("UPDATE claim SET held = ? WHERE id = ?", claim.isHeld(), claim.getId());
456	    }
457	
458	    /** Record that the claim's late charge is waived. */
459	    public void waive(Claim claim) {
460	        jdbc.update("UPDATE claim SET waived = ? WHERE id = ?", claim.isWaived(), claim.getId());
461	    }
462	
463	    /** Record the day the claim was last reminded, and whether it has been escalated. */
464	    public void remind(Claim claim) {
465	        jdbc.update("UPDATE claim SET reminded_on = ?, escalated = ? WHERE id = ?", Date.valueOf(claim.getRemindedOn()),
466	                claim.isEscalated(), claim.getId());
467	    }
468	
469	    /** The number the sheet's next bulk settle batch takes: one past its last. */
470	    public int nextBatch(String sheetId) {
471	        Integer last = jdbc.queryForObject("SELECT MAX(batch) FROM claim WHERE sheet_id = ?", Integer.class, sheetId);
472	        return last == null ? 1 : last + 1;
473	    }
474	
475	    /** Insert a new claim (assigning its id) or update an existing one. */
476	    public void save(Claim claim) {
477	        if (claim.getId() != null) {
478	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, proof_photos = ?, locked_by = ?, ref = ?, tags = ?, tags_used = ?, void_reason = ?, edited_by = ?, batch = ? WHERE id = ?",
479	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
480	                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
481	                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getProofs(), claim.getProofPhotos(), claim.getLockedBy(), claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(), claim.getEditedBy(), claim.getBatch(), claim.getId());
482	            return;
483	        }
484	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
485	        jdbc.update(con -> {
486	            PreparedStatement ps = con.prepareStatement(
487	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, number, opened_by, split_from, late_entry, ref, tags, tags_used, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
488	                    new String[] { "id" });
489	            ps.setString(1, claim.getSheetId());
490	            ps.setLong(2, claim.getPersonId());
491	            ps.setBigDecimal(3, claim.getAmount());
492	            ps.setDate(4, Date.valueOf(claim.getDate()));
493	            ps.setString(5, claim.getNote());
494	            ps.setString(6, claim.getStatus().name());
495	            ps.setString(7, claim.getCorrects());
496	            ps.setDate(8, Date.valueOf(claim.getDueBy()));
497	            ps.setString(9, claim.getNumber());
498	            ps.setString(10, claim.getOpenedBy());
499	            ps.setString(11, claim.getSplitFrom());
500	            ps.setBoolean(12, claim.isLateEntry());
501	            ps.setString(13, claim.getRef());
502	            ps.setString(14, claim.getTags());
503	            ps.setString(15, claim.getTagsUsed());
504	            ps.setObject(16, claim.getDueTerms(), Types.INTEGER);
505	            return ps;
506	        }, keys);
507	        claim.setId(keys.getKey().longValue());
508	    }
509	
510	    private static Claim claim(ResultSet rs, int i) throws SQLException {
511	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
512	                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
513	                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
514	                rs.getBigDecimal("due"), rs.getString("opened_by"));
515	        claim.setStated(rs.getBoolean("stated"));
516	        claim.setStatedDue(rs.getBigDecimal("stated_due"));
517	        claim.setCorrects(rs.getString("corrects"));
518	        claim.setDueBy(rs.getDate("due_by").toLocalDate());
519	        claim.setProofs(rs.getInt("proofs"));
520	        claim.setProofPhotos(rs.getInt("proof_photos"));
521	        claim.setSplitFrom(rs.getString("split_from"));
522	        claim.setLockedBy(rs.getString("locked_by"));
523	        claim.setLateEntry(rs.getBoolean("late_entry"));
524	        claim.setRef(rs.getString("ref"));
525	        claim.setTagsUsed(rs.getString("tags_used"));
526	        claim.setTags(rs.getString("tags"));
527	        claim.setVoidReason(rs.getString("void_reason"));
528	        claim.setEditedBy(rs.getString("edited_by"));
529	        int terms = rs.getInt("due_terms");
530	        claim.setDueTerms(rs.wasNull() ? null : terms);
531	        int batch = rs.getInt("batch");
532	        claim.setBatch(rs.wasNull() ? null : batch);
533	        long addedSeq = rs.getLong("added_seq");
534	        claim.setAddedSeq(rs.wasNull() ? null : addedSeq);
535	        Date reminded = rs.getDate("reminded_on");
536	        claim.setRemindedOn(reminded != null ? reminded.toLocalDate() : null);
537	        claim.setEscalated(rs.getBoolean("escalated"));
538	        claim.setWaived(rs.getBoolean("waived"));
539	        claim.setHeld(rs.getBoolean("held"));
540	        Date until = rs.getDate("deferred_until");
541	        Date today = rs.getDate("sheet_today");
542	        claim.setDeferredUntil(until != null ? until.toLocalDate() : null);
543	        claim.setDeferred(until != null && today != null && today.toLocalDate().isBefore(until.toLocalDate()));
544	        return claim;
545	    }
546	}
