package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person as the screen sees it, with their statement count, and the last statement's due-total
 *  (two decimals, null when it was n/a or none was taken) and date (yyyy-mm-dd, null when none was),
 *  and whether they are retired and from when (yyyy-mm-dd, null when not retired), and each past
 *  retirement's dates, in the order they ended,
 *  and whether they have any hold and each hold's dates, and the ids of the people they have named as patrons. `grade` is
 *  the grade in force on the sheet's today; `grades` every grade recorded, by from-date (null: from
 *  the beginning of time, first); `terms` the person's own terms in force on the sheet's today (null: none); `contact` their
 *  contact (null: none); `aliases` their aliases, sorted as names are compared; `clashing` whether
 *  their name or an alias is used on another sheet of their sheet's tree; `origin` the sheet they were
 *  transferred from (null: they were not); `tags` their tags, sorted (empty: none);
 *  `snapshots` their snapshot lines, oldest first ("<day left> <due-total>");
 *  `statementLines` their statements still standing, in the order taken ("<statement date> <due-total>");
 *  `ownTerms` their own terms from the beginning of time (null: none); `datedTerms` every dated terms
 *  recorded, by from-date (`terms` null: none from then); `flag` the reason of their flag while it is
 *  in force (null: none in force); `approver` the user who may approve or reject their PENDING
 *  claims as a steward may (null: none). */
public record PersonResponse(long id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        List<RetirementDates> pastRetirements,
        boolean held, List<HoldDates> holds, List<Long> patrons, List<GradeFrom> grades, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin, List<String> tags,
        List<String> snapshots, List<String> statementLines, Integer ownTerms, List<TermsFrom> datedTerms, String flag,
        String approver) {

    /** A hold's dates (yyyy-mm-dd; `to` null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    /** A past retirement's dates (yyyy-mm-dd): retired from `from`, unretired on `to`. */
    public record RetirementDates(String from, String to) {
    }

    public record GradeFrom(String grade, String from) {
    }

    public record TermsFrom(Integer terms, String from) {
    }

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() != null ? person.getStatedTotal().toPlainString() : null,
                person.getStatementDate() != null ? person.getStatementDate().toString() : null,
                person.isRetired(), person.getRetiredFrom() != null ? person.getRetiredFrom().toString() : null,
                person.getPastRetirements().stream()
                        .map(r -> new RetirementDates(r.from().toString(), r.to().toString()))
                        .toList(),
                person.isHeld(),
                person.getHolds().stream()
                        .map(h -> new HoldDates(h.from().toString(), h.to() != null ? h.to().toString() : null))
                        .toList(),
                List.copyOf(person.getPatronIds()),
                person.getGrades().entrySet().stream()
                        .map(e -> new GradeFrom(e.getValue(), e.getKey().equals(LocalDate.MIN) ? null : e.getKey().toString()))
                        .toList(),
                person.getTermsInForce(), person.getContact(), List.copyOf(person.getAliases()),
                person.isClashing(), person.getOriginSheet(),
                person.getTags() == null ? List.of() : List.of(person.getTags().split(",")),
                List.copyOf(person.getSnapshots()), List.copyOf(person.getStatementLines()), person.getTerms(),
                person.getDatedTerms().entrySet().stream()
                        .map(e -> new TermsFrom(e.getValue(), e.getKey().toString()))
                        .toList(),
                person.isFlagged() ? person.getFlagReason() : null, person.getApprover());
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID; a steward may also void a SETTLED claim within 7 days of its settlement.
 *  A DRAFT whose due is above the sheet's review threshold goes REVIEW when opened, until a steward
 *  reviews it to OPEN (or it is voided); a REVIEW claim counts nowhere but in the status counts.
 *  A DRAFT can be DELETED, and restored to DRAFT on the same sheet's today; a DELETED claim counts nowhere. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still open: OPEN, or PENDING (handled like an OPEN one: it goes overdue,
     *  bears the late charge and a hold takes it out of the totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order (people in list order, each
 *  person's newest claim first), so their numbers follow that order. Each is opened as a single
 *  open would be — its own audit line, then the figures it moved; one that cannot be opened (or is
 *  not on the sheet) is left as it is and counted as refused. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpen bulk, Claims claims, People people,
            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            ClaimLog log, Sheets sheets, Watches watches, Audit audit, VoidReasons voidReasons, Out<BulkOpenResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.OPEN, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int opened = 0;
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claims.save(claim);
                record.record(change, claim, people, log, watches, audit);
                rollup.record(sheetId, before, bulk.user());
                opened++;
            }
        }
        result.set(new BulkOpenResult(opened, bulk.claimIds().size() - opened));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** The number a claim gets when it is opened. While the sheet's period numbering from is set and
 *  the sheet's today is on or after it, the claim is numbered within the period its due-by falls in
 *  (<period name>-<n>), or X-<n> when it falls in none; otherwise it takes the next number within
 *  the fiscal year its due-by falls in (FY<yyyy>-<n>, counting from 1 each fiscal year, the sequence
 *  shared across the sheet's tree). */
@Service
public class ClaimNumbers {

    /** The sequence of claims in no period. */
    public static final String NO_PERIOD = "X";

    private final Sheets sheets;
    private final Settings settings;
    private final Periods periods;

    public ClaimNumbers(Sheets sheets, Settings settings, Periods periods) {
        this.sheets = sheets;
        this.settings = settings;
        this.periods = periods;
    }

    public String next(Claim claim) {
        String sheetId = claim.getSheetId();
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            int fy = fiscalYear(claim.getDueBy(), settings.fiscalStartMonth(sheetId));
            return "FY" + fy + "-" + sheets.nextFiscalNumber(sheetId, fy);
        }
        String seq = periods.onSheet(sheetId).stream().filter(p -> p.contains(claim.getDueBy()))
                .map(Period::name).findFirst().orElse(NO_PERIOD);
        return seq + "-" + sheets.nextPeriodNumber(sheetId, seq);
    }

    /** The fiscal year (the yyyy of FY<yyyy>, the calendar year its first day falls in) a date is in. */
    static int fiscalYear(LocalDate date, int startMonth) {
        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
    }
}
