378	   132	        java.util.Set<String> used = new java.util.HashSet<>();
379	   133	        for (String other : treeOf(sheetId)) {
380	   134	            used.addAll(jdbc.queryForList("SELECT name_key FROM PUBLIC.person WHERE sheet_id = ?", String.class, other));
381	   135	            used.addAll(jdbc.queryForList("SELECT alias_key FROM PUBLIC.person_alias WHERE sheet_id = ?", String.class, other));
