386	   140	    /** The other sheets of the sheet's tree, among the sheets that exist: its ancestors (its parent, the
387	   141	     *  parent's parent, and so on) and its descendants (the sheets naming it as parent, their children,
388	   142	     *  and so on). Not dated: read from the live sheets. */
389	   143	    public java.util.Set<String> treeOf(String sheetId) {
390	   144	        java.util.Set<String> tree = new java.util.LinkedHashSet<>();
391	   145	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
392	   146	        for (String sheet = parentOf(sheetId); sheet != null && seen.add(sheet); sheet = parentOf(sheet)) {
393	   147	            tree.add(sheet);
394	   148	        }
395	   149	        java.util.ArrayDeque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
396	   150	        java.util.Set<String> visited = new java.util.HashSet<>(List.of(sheetId));
397	   151	        while (!todo.isEmpty()) {
398	   152	            for (String child : jdbc.queryForList("SELECT sheet_id FROM PUBLIC.sheet_setting WHERE parent_id = ?",
399	   153	                    String.class, todo.poll())) {
400	   154	                if (visited.add(child)) {
401	   155	                    todo.add(child);
402	   156	                    tree.add(child);
403	   157	                }
404	   158	            }
405	   159	        }
406	   160	        tree.remove(sheetId);
407	   161	        tree.removeIf(sheet -> {
408	   162	            Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM PUBLIC.sheet WHERE id = ?", Integer.class, sheet);
409	   163	            return n == null || n == 0;
410	   164	        });
411	   165	        return tree;
412	   166	    }
