474	   228	    /** Swap the person with their neighbour in the list (the one above when `up`, else below), both
475	   229	     *  locked for the rest of the transaction; false (nothing written) when there is none, the person
476	   230	     *  being first or last. Not an edit: neither person's version changes. */
477	   231	    public boolean move(Person person, boolean up) {
478	   232	        String sheetId = person.getSheetId();
479	   233	        Long mine = jdbc.queryForObject("SELECT position FROM person WHERE id = ? FOR UPDATE", Long.class, person.getId());
480	   234	        List<long[]> neighbour = jdbc.query("SELECT id, position FROM person WHERE sheet_id = ? AND "
481	   235	                + (up ? "(position < ? OR (position = ? AND id < ?)) ORDER BY position DESC, id DESC"
482	   236	                        : "(position > ? OR (position = ? AND id > ?)) ORDER BY position, id")
483	   237	                + " LIMIT 1 FOR UPDATE",
484	   238	                (rs, i) -> new long[] { rs.getLong(1), rs.getLong(2) }, sheetId, mine, mine, person.getId());
485	   239	        if (neighbour.isEmpty()) return false;
486	   240	        long otherId = neighbour.get(0)[0];
487	   241	        long theirs = neighbour.get(0)[1];
488	   242	        if (theirs == mine) {
489	   243	            // Equal positions cannot be swapped: spread the sheet's positions out first.
490	   244	            renumber(sheetId);
491	   245	            mine = jdbc.queryForObject("SELECT position FROM person WHERE id = ?", Long.class, person.getId());
492	   246	            theirs = jdbc.queryForObject("SELECT position FROM person WHERE id = ?", Long.class, otherId);
493	   247	        }
494	   248	        jdbc.update("UPDATE person SET position = ? WHERE id = ?", theirs, person.getId());
495	   249	        jdbc.update("UPDATE person SET position = ? WHERE id = ?", mine, otherId);
496	   250	        return true;
497	   251	    }
