   118	                || !same(before.overdueTotal(), after.overdueTotal())) {
   119	            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
   120	                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
   121	        }
