   123	        if (threshold == null) return;
   124	        after.people().forEach((id, now) -> {
   125	            Snapshot.PersonFigures was = before.people().get(id);
   126	            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
