 51	     *  answer is into's id. */
 52	    public long transfer(Person person, String to, Person into) {
 53	        // The person arrives knowing the sheet they came from and their name there (the audit follows them back).
 54	        long fromId = person.getId();
 55	        long toId = into != null ? mergeInto(person, into) : insertPerson(person, to);
 56	        Person receiving = into != null ? into : people.find(to, toId);
 57	        people.takeStatements(person, receiving);
