 59	        List<Claim> kept = new ArrayList<>(claims.ofPerson(person.getSheetId(), fromId));
 60	        Collections.reverse(kept); // oldest listed first, so they keep their order
 61	        Map<Long, String> renumbered = renumber(kept, to);
 62	        for (Claim claim : kept) {
 63	            long newId = insertClaim(claim, to, toId, renumbered.get(claim.getId()));
 64	            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) "
 65	                    + "SELECT ?, ?, status, by_user, on_date, due FROM claim_log WHERE claim_id = ? ORDER BY id",
 66	                    to, newId, claim.getId());
 67	            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, comment_text) "
 68	                    + "SELECT ?, ?, by_user, on_date, comment_text FROM claim_comment WHERE claim_id = ? ORDER BY id",
 69	                    to, newId, claim.getId());
 70	            jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) "
 71	                    + "SELECT ?, ?, label, qty, unit FROM claim_line WHERE claim_id = ? ORDER BY id",
 72	                    to, newId, claim.getId());
 73	        }
 74	
 75	        for (Claim claim : kept) {
 76	            jdbc.update("DELETE FROM claim_log WHERE claim_id = ?", claim.getId());
 77	            jdbc.update("DELETE FROM claim_comment WHERE claim_id = ?", claim.getId());
 78	            jdbc.update("DELETE FROM claim_line WHERE claim_id = ?", claim.getId());
 79	            jdbc.update("DELETE FROM claim WHERE id = ?", claim.getId());
