104	                + "SELECT ?, ?, alias, alias_key FROM person_alias WHERE person_id = ? ORDER BY id",
105	                into.getSheetId(), into.getId(), person.getId());
106	        String name = person.getName().trim();
107	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, alias_key) VALUES (?, ?, ?, LOWER(?))",
108	                into.getSheetId(), into.getId(), name, name);
