118	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, "
119	                            + People.END_POSITION + ")", new String[] { "id" });
120	            ps.setString(1, to);
121	            ps.setString(2, person.getName());
122	            ps.setString(3, person.getFirstGrade());
123	            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
124	            ps.setString(5, person.getContact());
125	            ps.setString(6, person.getTags());
126	            ps.setString(7, person.getSheetId());
