143	    /** The new number on sheet `to` of each claim that had one, by its id, given in the order opened. */
144	    private Map<Long, String> renumber(List<Claim> kept, String to) {
145	        Map<Long, LocalDate> openedOn = new HashMap<>();
146	        for (Claim claim : kept) {
147	            if (claim.getNumber() == null) continue;
148	            List<Date> dates = jdbc.queryForList(
149	                    "SELECT on_date FROM claim_log WHERE claim_id = ? AND status = 'OPEN' ORDER BY id",
150	                    Date.class, claim.getId());
151	            openedOn.put(claim.getId(), dates.isEmpty() ? claim.getDate() : dates.get(0).toLocalDate());
152	        }
153	        List<Claim> numbered = kept.stream().filter(c -> c.getNumber() != null)
154	                .sorted(Comparator.comparing((Claim c) -> openedOn.get(c.getId())).thenComparing(Claim::getId))
155	                .toList();
156	        Map<Long, String> renumbered = new HashMap<>();
157	        for (Claim claim : numbered) {
158	            Claim there = new Claim(null, to, 0, claim.getAmount(), claim.getDate(), claim.getNote(),
159	                    claim.getStatus(), null, claim.getDue(), claim.getOpenedBy());
160	            there.setDueBy(claim.getDueBy());
161	            renumbered.put(claim.getId(), numbers.next(there));
162	        }
163	        return renumbered;
164	    }
