170	                    + "note, status, number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, "
171	                    + "proofs, proof_photos, split_from, locked_by, late_entry, reminded_on, escalated, waived, held, ref, tags, tags_used, void_reason, "
172	                    + "edited_by, due_terms, batch) SELECT ?, ?, amount, claim_date, note, status, ?, due, opened_by, "
173	                    + "stated, stated_due, corrects, due_by, deferred_until, proofs, proof_photos, split_from, NULL, late_entry, reminded_on, escalated, waived, held, "
174	                    + "NULL, tags, tags_used, void_reason, edited_by, due_terms, NULL FROM claim WHERE id = ?",
175	                    new String[] { "id" });
176	            ps.setString(1, to);
177	            ps.setLong(2, toId);
178	            ps.setString(3, number);
179	            ps.setLong(4, claim.getId());
180	            return ps;
181	        }, keys);
182	        return keys.getKey().longValue();
183	    }
